/* WholesalePro v1.0 — local-first wholesale business manager.
   Data is stored in this browser via localStorage. See README for production notes. */
(() => {
  'use strict';
  const STORAGE_KEY = 'wholesalepro.data.v1';
  const ICONS = {
    grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 8v6m3-3h-6"/>',
    box:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="M3 8v9l9 5 9-5V8M12 13v9"/>',
    file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
    receipt:'<path d="M4 2v20l4-2 4 2 4-2 4 2V2l-4 2-4-2-4 2-4-2Z"/><path d="M8 9h8M8 13h8"/>',
    truck:'<path d="M3 6h12v12H3zM15 10h4l3 3v5h-7z"/><circle cx="7.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/>',
    building:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M9 21V8h6v13M7 8h.01M7 12h.01M7 16h.01M17 8h.01M17 12h.01M17 16h.01"/>',
    wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 15h.01"/>',
    chart:'<path d="M3 3v18h18"/><path d="m8 14 4-4 3 3 6-7"/>',
    settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.5.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.5-.9l-1.7.6-1.4-2.4 1.4-1.1a7 7 0 0 1 0-1.8l-1.4-1.1 1.4-2.4 1.7.6a8 8 0 0 1 1.5-.9l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.5.9l1.7-.6 1.4 2.4-1.4 1.1a7 7 0 0 1 0 1.8Z" transform="translate(-2 -2)"/>',
    spark:'<path d="m12 3 1.7 5.3L19 10l-5.3 1.7L12 17l-1.7-5.3L5 10l5.3-1.7L12 3Z"/><path d="m19 16 .8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8L19 16Z"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m18 6-12 12M6 6l12 12"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',
    edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m4 4v7m6-7v7"/>',
    eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>',
    upload:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12"/>',
    print:'<path d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6z"/>',
    message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',
    alert:'<path d="m10.3 3.9-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.6 9a7 7 0 0 1 11.6-2L20 12M4 12l2.8 5a7 7 0 0 0 11.6-2"/>',
    filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',
    cash:'<rect x="2" y="6" width="20" height="13" rx="2"/><circle cx="12" cy="12.5" r="2.5"/><path d="M6 10h.01M18 15h.01"/>',
    calendarClock:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M16 2v4M8 2v4M3 9h18m-9 4v3l2 1"/>',
    percent:'<path d="M19 5 5 19"/><circle cx="6.5" cy="6.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/>',
    minus:'<path d="M5 12h14"/>',
  };
  const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] || ICONS.spark}</svg>`;
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
  const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
  const today = () => new Date().toISOString().slice(0,10);
  const fmtDate = (d) => d ? new Date(`${d}T00:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}) : '—';
  const money = (n) => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n)||0);
  const num = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
  const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials = (s='?') => String(s).trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase() || '?';
  const DEFAULTS = {
    settings:{businessName:'Your Wholesale Business',gstin:'',state:'Kerala',address:'',phone:'',email:'',invoicePrefix:'INV',quotePrefix:'QT',purchasePrefix:'PUR',lowStock:15,overStock:100,expiryDays:30,pricingMode:'exclusive',terms:'Goods once sold will be taken back only as per agreed terms.'},
    customers:[],suppliers:[],products:[],quotations:[],invoices:[],purchases:[],expenses:[],stockMovements:[]
  };
  let db = loadData();
  let activePage = 'dashboard';
  let pageSearch = '';
  let chartRange = '6';

  function loadData(){
    try{
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
      if(!saved) return structuredClone(DEFAULTS);
      const merged = {...structuredClone(DEFAULTS),...saved,settings:{...DEFAULTS.settings,...(saved.settings||{})}};
      for(const k of ['customers','suppliers','products','quotations','invoices','purchases','expenses','stockMovements']) if(!Array.isArray(merged[k])) merged[k]=[];
      return merged;
    }catch(e){ console.warn('Could not read local data',e); return structuredClone(DEFAULTS); }
  }
  function saveData(){
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));updateProfileInitial();}
    catch(e){toast('Could not save data. Your browser storage may be full.','error');}
  }
  function toast(message,type='success'){
    const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastStack').appendChild(el);setTimeout(()=>el.remove(),3400);
  }
  function updateProfileInitial(){ $('#profileButton').textContent=initials(db.settings.businessName).slice(0,1); }
  function setIcons(root=document){ $$('[data-icon]',root).forEach(el=>{const name=el.getAttribute('data-icon');el.innerHTML=icon(name);}); }
  function pageTitle(page){return ({dashboard:'Dashboard',customers:'Customers',products:'Products & stock',quotations:'Quotations',invoices:'Invoices & sales',purchases:'Purchases',suppliers:'Suppliers',expenses:'Expenses',reports:'Reports',settings:'Settings'})[page]||'Dashboard';}
  function pageHeader(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(db.settings.businessName)}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function emptyState(title,desc,button=''){return `<div class="empty-state"><div class="empty-icon">${icon('box')}</div><strong>${title}</strong><p>${desc}</p>${button}</div>`;}
  function statusPill(label,tone='gray'){return `<span class="status ${tone}">${esc(label)}</span>`;}
  function findCustomer(id){return db.customers.find(x=>x.id===id)||null;}
  function findSupplier(id){return db.suppliers.find(x=>x.id===id)||null;}
  function findProduct(id){return db.products.find(x=>x.id===id)||null;}
  function docTotal(items, customerState){return calcTotals(items,customerState);}
  function stateIsInter(customerState){const own=(db.settings.state||'').trim().toLowerCase();const theirs=(customerState||'').trim().toLowerCase();return !!(own&&theirs&&own!==theirs);}
  function calcTotals(items, customerState){
    let taxable=0,cgst=0,sgst=0,igst=0,discount=0;
    const inter=stateIsInter(customerState);
    for(const item of items){
      const gross=num(item.qty)*num(item.rate);const disc=gross*num(item.discount||0)/100;discount+=disc;
      const net=gross-disc;const rate=num(item.gstRate);
      const base=(db.settings.pricingMode==='inclusive' && rate>0)?net/(1+rate/100):net;
      const tax=base*rate/100;taxable+=base;
      if(inter) igst+=tax; else {cgst+=tax/2;sgst+=tax/2;}
    }
    const total=taxable+cgst+sgst+igst;
    return {taxable,cgst,sgst,igst,total,discount,inter,roundOff:Math.round(total)-total,grand:Math.round(total)};
  }
  function normalizeDocItems(raw){return raw.map(x=>{const p=findProduct(x.productId);return {productId:x.productId,name:p?.name||x.name||'Item',sku:p?.sku||x.sku||'',hsn:p?.hsn||x.hsn||'',unit:p?.unit||x.unit||'pcs',qty:num(x.qty),rate:num(x.rate),discount:num(x.discount),gstRate:num(p?.gstRate ?? x.gstRate)};}).filter(x=>x.name&&x.qty>0);}
  function stockStatus(p){const low=num(p.lowStock??db.settings.lowStock),high=num(p.overStock??db.settings.overStock);if(num(p.stock)<=low)return ['Low stock','red'];if(num(p.stock)>high)return ['Overstock','amber'];return ['In stock','green'];}
  function expiryAlerts(){const now=new Date(`${today()}T00:00:00`);const out=[];db.products.filter(p=>p.trackExpiry).forEach(p=>(p.batches||[]).forEach(b=>{if(!b.expiryDate||num(b.qty)<=0)return;const diff=Math.ceil((new Date(`${b.expiryDate}T00:00:00`)-now)/86400000);if(diff<=num(db.settings.expiryDays)&&diff>=0)out.push({product:p,batch:b,days:diff});if(diff<0)out.push({product:p,batch:b,days:diff});}));return out.sort((a,b)=>a.days-b.days);}
  function outstandingInvoices(){return db.invoices.filter(i=>num(i.grandTotal)-num(i.paidAmount)>.009);}
  function invoiceStatus(i){const due=Math.max(0,num(i.grandTotal)-num(i.paidAmount));if(due<=.009)return ['Paid','green'];if(num(i.paidAmount)>0)return ['Partially paid','amber'];if(i.dueDate&&i.dueDate<today())return ['Overdue','red'];return ['Unpaid','red'];}
  function monthStart(date=new Date()){return new Date(date.getFullYear(),date.getMonth(),1).toISOString().slice(0,10);}
  function monthInvoices(){const start=monthStart();return db.invoices.filter(i=>i.date>=start&&i.date<=today());}
  function monthExpenses(){const start=monthStart();return db.expenses.filter(e=>e.date>=start&&e.date<=today());}
  function customerBalance(id){return db.invoices.filter(i=>i.customerId===id).reduce((s,i)=>s+Math.max(0,num(i.grandTotal)-num(i.paidAmount)),0);}
  function drawSalesChart(){
    const canvas=$('#salesChart');if(!canvas)return;
    const ctx=canvas.getContext('2d');const rect=canvas.getBoundingClientRect();const ratio=window.devicePixelRatio||1;canvas.width=Math.max(300,rect.width*ratio);canvas.height=rect.height*ratio;ctx.scale(ratio,ratio);
    const w=rect.width,h=rect.height,pad={l:42,r:12,t:12,b:28};const months=Number(chartRange);const now=new Date();const labels=[];const sales=[],expenses=[];
    for(let k=months-1;k>=0;k--){const d=new Date(now.getFullYear(),now.getMonth()-k,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;labels.push(d.toLocaleDateString('en-IN',{month:'short'}));sales.push(db.invoices.filter(x=>(x.date||'').startsWith(key)).reduce((s,x)=>s+num(x.grandTotal),0));expenses.push(db.expenses.filter(x=>(x.date||'').startsWith(key)).reduce((s,x)=>s+num(x.amount),0));}
    const max=Math.max(100,...sales,...expenses)*1.12;const plotW=w-pad.l-pad.r,plotH=h-pad.t-pad.b;ctx.clearRect(0,0,w,h);ctx.font='10px DM Sans';ctx.fillStyle='#9aa4b2';ctx.strokeStyle='#edf0f5';ctx.lineWidth=1;
    for(let j=0;j<=4;j++){const y=pad.t+plotH*j/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();const val=max*(1-j/4);ctx.textAlign='right';ctx.fillText(val>=100000?`₹${(val/100000).toFixed(1)}L`:val>=1000?`₹${(val/1000).toFixed(0)}k`:`₹${val.toFixed(0)}`,pad.l-8,y+3);}
    labels.forEach((label,i)=>{const x=pad.l+(labels.length===1?plotW/2:plotW*i/(labels.length-1));ctx.textAlign='center';ctx.fillStyle='#9aa4b2';ctx.fillText(label,x,h-7);});
    const series=[{values:sales,color:'#4773ed'},{values:expenses,color:'#24a77a'}];
    series.forEach(s=>{ctx.beginPath();s.values.forEach((v,i)=>{const x=pad.l+(labels.length===1?plotW/2:plotW*i/(labels.length-1));const y=pad.t+plotH-(v/max)*plotH;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.strokeStyle=s.color;ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.stroke();s.values.forEach((v,i)=>{const x=pad.l+(labels.length===1?plotW/2:plotW*i/(labels.length-1));const y=pad.t+plotH-(v/max)*plotH;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fillStyle=s.color;ctx.fill();});});
  }
  function renderDashboard(){
    const invoices=monthInvoices(),expenses=monthExpenses();const revenue=invoices.reduce((s,i)=>s+num(i.grandTotal),0),expenseTotal=expenses.reduce((s,e)=>s+num(e.amount),0),outstanding=outstandingInvoices().reduce((s,i)=>s+Math.max(0,num(i.grandTotal)-num(i.paidAmount)),0);
    const low=db.products.filter(p=>num(p.stock)<=num(p.lowStock??db.settings.lowStock));const high=db.products.filter(p=>num(p.stock)>num(p.overStock??db.settings.overStock));const exp=expiryAlerts();const due=outstandingInvoices().filter(i=>i.dueDate&&i.dueDate<today());const pendingQuotes=db.quotations.filter(q=>!['Converted','Accepted'].includes(q.status)&&(!q.validUntil||q.validUntil>=today()));
    const recent=[...db.invoices].sort((a,b)=>(b.createdAt||b.date||'').localeCompare(a.createdAt||a.date||'')).slice(0,5);
    return `${pageHeader('Business overview','A clear picture of your sales, stock and day-to-day priorities.',`<button class="btn btn-secondary" data-action="export-data">${icon('download')} Backup data</button><button class="btn btn-primary" data-action="new-invoice">${icon('plus')} Create invoice</button>`)}
      <div class="stats-grid">
        <div class="stat-card"><div class="stat-top">Revenue this month <span class="stat-icon">${icon('chart')}</span></div><div class="stat-value">${money(revenue)}</div><div class="stat-foot"><strong>${invoices.length}</strong> invoices raised this month</div></div>
        <div class="stat-card"><div class="stat-top">Expenses this month <span class="stat-icon orange">${icon('wallet')}</span></div><div class="stat-value">${money(expenseTotal)}</div><div class="stat-foot"><strong>${expenses.length}</strong> expense entries this month</div></div>
        <div class="stat-card"><div class="stat-top">Total customers <span class="stat-icon green">${icon('users')}</span></div><div class="stat-value">${db.customers.length}</div><div class="stat-foot">Registered customer accounts</div></div>
        <div class="stat-card"><div class="stat-top">Outstanding payments <span class="stat-icon red">${icon('cash')}</span></div><div class="stat-value">${money(outstanding)}</div><div class="stat-foot"><strong>${outstandingInvoices().length}</strong> invoices awaiting payment</div></div>
      </div>
      <div class="quick-grid">
        <button class="quick-action" data-action="new-customer"><span class="quick-icon">${icon('users')}</span><span><strong>Add customer</strong><small>Save customer details</small></span></button>
        <button class="quick-action" data-action="new-product"><span class="quick-icon">${icon('box')}</span><span><strong>Add product</strong><small>Update your catalogue</small></span></button>
        <button class="quick-action" data-action="new-quotation"><span class="quick-icon">${icon('file')}</span><span><strong>New quotation</strong><small>Prepare a price offer</small></span></button>
        <button class="quick-action" data-action="new-expense"><span class="quick-icon">${icon('wallet')}</span><span><strong>Record expense</strong><small>Track business costs</small></span></button>
      </div>
      <div class="dashboard-grid">
        <section class="panel"><div class="panel-head"><div><div class="panel-title">Sales & expenses</div><div class="panel-subtitle">Monthly movement based on recorded transactions</div></div><select class="period-select" id="chartRange"><option value="6" ${chartRange==='6'?'selected':''}>Last 6 months</option><option value="12" ${chartRange==='12'?'selected':''}>Last 12 months</option></select></div><div class="chart-legend"><span><i class="legend-dot" style="background:#4773ed"></i>Sales</span><span><i class="legend-dot" style="background:#24a77a"></i>Expenses</span></div><div class="chart-wrap"><canvas id="salesChart"></canvas></div></section>
        <section class="panel"><div class="panel-head"><div><div class="panel-title">Needs attention</div><div class="panel-subtitle">Important items to review</div></div><span class="status ${low.length+high.length+exp.length+due.length+pendingQuotes.length?'amber':'green'}">${low.length+high.length+exp.length+due.length+pendingQuotes.length} alerts</span></div><div class="alert-list">
          ${low.slice(0,3).map(p=>`<div class="alert-row"><span class="alert-mark">${icon('alert')}</span><span class="alert-copy"><strong>${esc(p.name)}</strong><small>Stock is below the minimum level</small></span><span class="alert-value">${num(p.stock)} ${esc(p.unit||'pcs')}</span></div>`).join('')}
          ${high.slice(0,2).map(p=>`<div class="alert-row"><span class="alert-mark amber">${icon('box')}</span><span class="alert-copy"><strong>${esc(p.name)}</strong><small>Stock is above the preferred level</small></span><span class="alert-value">${num(p.stock)} ${esc(p.unit||'pcs')}</span></div>`).join('')}
          ${exp.slice(0,3).map(x=>`<div class="alert-row"><span class="alert-mark amber">${icon('clock')}</span><span class="alert-copy"><strong>${esc(x.product.name)}</strong><small>Batch ${esc(x.batch.batchNo||'—')} · ${x.days<0?'Expired':x.days===0?'Expires today':`Expires in ${x.days} days`}</small></span><span class="alert-value">${num(x.batch.qty)} ${esc(x.product.unit||'pcs')}</span></div>`).join('')}
          ${due.slice(0,2).map(i=>`<div class="alert-row"><span class="alert-mark">${icon('clock')}</span><span class="alert-copy"><strong>${esc(i.number)} · ${esc(findCustomer(i.customerId)?.name||'Customer')}</strong><small>Payment overdue since ${fmtDate(i.dueDate)}</small></span><span class="alert-value">${money(i.grandTotal-i.paidAmount)}</span></div>`).join('')}
          ${pendingQuotes.slice(0,2).map(q=>`<div class="alert-row"><span class="alert-mark amber">${icon('file')}</span><span class="alert-copy"><strong>${esc(q.number)} · ${esc(findCustomer(q.customerId)?.name||'Customer')}</strong><small>Quotation awaiting customer response</small></span><span class="alert-value">${money(q.grandTotal??q.grand)}</span></div>`).join('')}
          ${!low.length&&!high.length&&!exp.length&&!due.length&&!pendingQuotes.length?`<div class="empty-state" style="padding:25px 5px"><div class="empty-icon">${icon('check')}</div><strong>All clear for now</strong><p>No stock or payment alerts need attention.</p></div>`:''}
        </div></section>
      </div>
      <div class="lower-grid">
        <section class="panel"><div class="panel-head"><div><div class="panel-title">Recent invoices</div><div class="panel-subtitle">Latest sales documents</div></div><button class="btn btn-secondary btn-sm" data-page="invoices">View all ${icon('arrow')}</button></div>
          ${recent.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${recent.map(i=>{const st=invoiceStatus(i);return `<tr><td><strong>${esc(i.number)}</strong></td><td>${esc(findCustomer(i.customerId)?.name||'—')}</td><td>${fmtDate(i.date)}</td><td><strong>${money(i.grandTotal)}</strong></td><td>${statusPill(st[0],st[1])}</td></tr>`;}).join('')}</tbody></table></div>`:emptyState('No invoices yet','Create your first invoice to start tracking sales.','<button class="btn btn-primary btn-sm" data-action="new-invoice">Create invoice</button>')}
        </section>
        <section class="panel"><div class="panel-head"><div><div class="panel-title">Stock snapshot</div><div class="panel-subtitle">Your current product inventory</div></div><button class="btn btn-secondary btn-sm" data-page="products">Manage stock ${icon('arrow')}</button></div>
          ${db.products.length?`<div class="alert-list">${[...db.products].sort((a,b)=>num(a.stock)-num(b.stock)).slice(0,5).map(p=>{const s=stockStatus(p),max=Math.max(1,num(p.overStock??db.settings.overStock));const pct=Math.min(100,Math.max(4,num(p.stock)/max*100));return `<div class="alert-row"><span class="product-thumb">${esc(initials(p.name))}</span><span class="alert-copy"><strong>${esc(p.name)}</strong><small>${esc(p.sku||'No SKU')} · ${statusPill(s[0],s[1])}</small></span><span class="alert-value"><span class="stock-meter"><i class="${s[1]==='red'?'low':s[1]==='amber'?'high':''}" style="width:${pct}%"></i></span>${num(p.stock)}</span></div>`;}).join('')}</div>`:emptyState('No products added','Add products to monitor stock levels.','<button class="btn btn-primary btn-sm" data-action="new-product">Add product</button>')}
        </section>
      </div>`;
  }

  function renderCustomers(){
    const list=db.customers.filter(c=>[c.name,c.phone,c.whatsapp,c.gstin,c.city].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));
    return `${pageHeader('Customers','Keep customer contact details, GST information and payment history together.',`<button class="btn btn-primary" data-action="new-customer">${icon('plus')} Add customer</button>`)}
      <div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search name, phone or GSTIN..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} customer${list.length===1?'':'s'}</span></div></div>
      <section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Contact</th><th>GSTIN</th><th>State</th><th>Outstanding</th><th>Actions</th></tr></thead><tbody>${list.map(c=>`<tr><td><div class="table-primary"><span class="avatar-small">${esc(initials(c.name))}</span><span><strong>${esc(c.name)}</strong><small class="table-muted" style="display:block">${esc(c.customerType||'Retailer')}</small></span></div></td><td>${esc(c.phone||'—')}<small class="table-muted" style="display:block">WA: ${esc(c.whatsapp||'—')}</small></td><td>${esc(c.gstin||'Unregistered')}</td><td>${esc(c.state||'—')}</td><td><strong>${money(customerBalance(c.id))}</strong></td><td><div class="table-actions"><button class="tiny-action" title="Create quotation" data-action="customer-quote" data-id="${c.id}">${icon('file')}</button><button class="tiny-action" title="Edit customer" data-action="edit-customer" data-id="${c.id}">${icon('edit')}</button><button class="tiny-action" title="Delete customer" data-action="delete-customer" data-id="${c.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No customers found','Add a customer or change your search.','<button class="btn btn-primary btn-sm" data-action="new-customer">Add customer</button>')}</section>`;
  }
  function renderProducts(){
    const list=db.products.filter(p=>[p.name,p.sku,p.category,p.hsn].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));
    return `${pageHeader('Products & stock','Manage your catalogue, stock quantities, batch numbers and expiry dates.',`<button class="btn btn-secondary" data-action="stock-adjust">${icon('refresh')} Stock adjustment</button><button class="btn btn-primary" data-action="new-product">${icon('plus')} Add product</button>`)}
      <div class="stats-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="stat-card"><div class="stat-top">Products listed <span class="stat-icon">${icon('box')}</span></div><div class="stat-value">${db.products.length}</div><div class="stat-foot">Unique product records</div></div><div class="stat-card"><div class="stat-top">Low stock items <span class="stat-icon red">${icon('alert')}</span></div><div class="stat-value">${db.products.filter(p=>num(p.stock)<=num(p.lowStock??db.settings.lowStock)).length}</div><div class="stat-foot">At or below minimum level</div></div><div class="stat-card"><div class="stat-top">Near expiry batches <span class="stat-icon orange">${icon('clock')}</span></div><div class="stat-value">${expiryAlerts().length}</div><div class="stat-foot">Within configured alert window</div></div></div>
      <div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search product, SKU or HSN..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} products</span></div></div>
      <section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>SKU / HSN</th><th>Category</th><th>Stock on hand</th><th>GST</th><th>Sale price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(p=>{const s=stockStatus(p),max=Math.max(1,num(p.overStock??db.settings.overStock)),pct=Math.min(100,Math.max(3,num(p.stock)/max*100));return `<tr><td><div class="product-cell"><span class="product-thumb">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small class="table-muted" style="display:block">${esc(p.unit||'pcs')}</small></span></div></td><td>${esc(p.sku||'—')}<small class="table-muted" style="display:block">HSN: ${esc(p.hsn||'—')}</small></td><td>${esc(p.category||'—')}</td><td><span class="stock-meter"><i class="${s[1]==='red'?'low':s[1]==='amber'?'high':''}" style="width:${pct}%"></i></span><strong>${num(p.stock)}</strong> <span class="table-muted">${esc(p.unit||'pcs')}</span></td><td>${num(p.gstRate)}%</td><td><strong>${money(p.sellingPrice)}</strong></td><td>${statusPill(s[0],s[1])}</td><td><div class="table-actions"><button class="tiny-action" title="Adjust stock" data-action="adjust-product" data-id="${p.id}">${icon('refresh')}</button><button class="tiny-action" title="Edit product" data-action="edit-product" data-id="${p.id}">${icon('edit')}</button><button class="tiny-action" title="Delete product" data-action="delete-product" data-id="${p.id}">${icon('trash')}</button></div></td></tr>`;}).join('')}</tbody></table></div>`:emptyState('No products found','Add products to start managing inventory.','<button class="btn btn-primary btn-sm" data-action="new-product">Add product</button>')}</section>
      <section class="panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Batch expiry watch</div><div class="panel-subtitle">Products with expiry dates inside the alert window, including already expired batches</div></div></div>${expiryAlerts().length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Batch</th><th>Quantity</th><th>Expiry</th><th>Alert</th></tr></thead><tbody>${expiryAlerts().slice(0,8).map(x=>`<tr><td><strong>${esc(x.product.name)}</strong></td><td>${esc(x.batch.batchNo||'—')}</td><td>${num(x.batch.qty)} ${esc(x.product.unit||'pcs')}</td><td>${fmtDate(x.batch.expiryDate)}</td><td>${statusPill(x.days<0?'Expired':x.days===0?'Expires today':`${x.days} days left`,x.days<=7?'red':'amber')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="muted" style="font-size:11px;padding:15px 0">No near-expiry batches have been recorded.</div>`}</section><section class="panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Recent stock movements</div><div class="panel-subtitle">A record of stock additions, removals and sales</div></div></div>${db.stockMovements.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Product</th><th>Reason</th><th>Reference / note</th><th>Quantity change</th></tr></thead><tbody>${db.stockMovements.slice(0,12).map(m=>`<tr><td>${fmtDate(m.date)}</td><td><strong>${esc(m.productName)}</strong></td><td>${esc(m.reason)}</td><td>${esc(m.note||'—')}</td><td><strong style="color:${m.delta>=0?'#15966a':'#d4515b'}">${m.delta>0?'+':''}${num(m.delta)}</strong></td></tr>`).join('')}</tbody></table></div>`:`<div class="muted" style="font-size:11px;padding:15px 0">Stock changes will appear here.</div>`}</section>`;
  }
  function renderQuotations(){const list=db.quotations.filter(q=>[q.number,findCustomer(q.customerId)?.name,q.status].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));return `${pageHeader('Quotations','Prepare price offers, share them with customers and convert accepted quotes into invoices.',`<button class="btn btn-primary" data-action="new-quotation">${icon('plus')} Create quotation</button>`)}<div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search quotation or customer..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} quotations</span></div></div><section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Quotation</th><th>Customer</th><th>Date</th><th>Valid until</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(q=>`<tr><td><strong>${esc(q.number)}</strong></td><td>${esc(findCustomer(q.customerId)?.name||'—')}</td><td>${fmtDate(q.date)}</td><td>${fmtDate(q.validUntil)}</td><td><strong>${money(q.grandTotal)}</strong></td><td>${statusPill(q.status||'Draft',q.status==='Accepted'?'green':q.status==='Converted'?'blue':q.status==='Sent'?'amber':'gray')}</td><td><div class="table-actions"><button class="tiny-action" title="Preview" data-action="view-quote" data-id="${q.id}">${icon('eye')}</button><button class="tiny-action" title="WhatsApp message" data-action="whatsapp-quote" data-id="${q.id}">${icon('message')}</button><button class="tiny-action" title="Mark accepted" data-action="accept-quote" data-id="${q.id}">${icon('check')}</button><button class="tiny-action" title="Convert to invoice" data-action="convert-quote" data-id="${q.id}">${icon('receipt')}</button><button class="tiny-action" title="Delete" data-action="delete-quote" data-id="${q.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No quotations yet','Create a quotation and share it with a customer.','<button class="btn btn-primary btn-sm" data-action="new-quotation">Create quotation</button>')}</section>`;}
  function renderInvoices(){const list=db.invoices.filter(i=>[i.number,findCustomer(i.customerId)?.name,invoiceStatus(i)[0]].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));return `${pageHeader('Invoices & sales','Create GST tax invoices, record payments and keep track of customer balances.',`<button class="btn btn-primary" data-action="new-invoice">${icon('plus')} Create tax invoice</button>`)}<div class="report-cards"><div class="report-mini"><span>Total invoices</span><strong>${db.invoices.length}</strong></div><div class="report-mini"><span>Total invoiced value</span><strong>${money(db.invoices.reduce((s,i)=>s+num(i.grandTotal),0))}</strong></div><div class="report-mini"><span>Outstanding</span><strong>${money(outstandingInvoices().reduce((s,i)=>s+num(i.grandTotal)-num(i.paidAmount),0))}</strong></div></div><div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search invoice or customer..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} invoices</span></div></div><section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Due date</th><th>Invoice total</th><th>Balance due</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(i=>{const st=invoiceStatus(i);return `<tr><td><strong>${esc(i.number)}</strong></td><td>${esc(findCustomer(i.customerId)?.name||'—')}</td><td>${fmtDate(i.date)}</td><td>${fmtDate(i.dueDate)}</td><td><strong>${money(i.grandTotal)}</strong></td><td><strong>${money(Math.max(0,num(i.grandTotal)-num(i.paidAmount)))}</strong></td><td>${statusPill(st[0],st[1])}</td><td><div class="table-actions"><button class="tiny-action" title="Preview / print" data-action="view-invoice" data-id="${i.id}">${icon('eye')}</button><button class="tiny-action" title="Record payment" data-action="add-payment" data-id="${i.id}">${icon('cash')}</button><button class="tiny-action" title="WhatsApp" data-action="whatsapp-invoice" data-id="${i.id}">${icon('message')}</button></div></td></tr>`;}).join('')}</tbody></table></div>`:emptyState('No invoices yet','Your sales invoices will appear here.','<button class="btn btn-primary btn-sm" data-action="new-invoice">Create tax invoice</button>')}</section>`;}
  function renderPurchases(){const list=db.purchases.filter(p=>[p.number,findSupplier(p.supplierId)?.name].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));return `${pageHeader('Purchases','Record supplier purchases and add received quantities to inventory.',`<button class="btn btn-primary" data-action="new-purchase">${icon('plus')} Record purchase</button>`)}<div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search purchase or supplier..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} purchases</span></div></div><section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Purchase ref.</th><th>Supplier</th><th>Date</th><th>Items</th><th>Total</th><th>Actions</th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.number)}</strong></td><td>${esc(findSupplier(p.supplierId)?.name||'—')}</td><td>${fmtDate(p.date)}</td><td>${(p.items||[]).length}</td><td><strong>${money(p.total)}</strong></td><td><div class="table-actions"><button class="tiny-action" title="View purchase" data-action="view-purchase" data-id="${p.id}">${icon('eye')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No purchases recorded','Record purchases when goods arrive from suppliers.','<button class="btn btn-primary btn-sm" data-action="new-purchase">Record purchase</button>')}</section>`;}
  function renderSuppliers(){const list=db.suppliers.filter(s=>[s.name,s.phone,s.gstin,s.city].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));return `${pageHeader('Suppliers','Maintain supplier contacts and purchase history.',`<button class="btn btn-primary" data-action="new-supplier">${icon('plus')} Add supplier</button>`)}<div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search supplier or GSTIN..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} suppliers</span></div></div><section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Supplier</th><th>Contact</th><th>GSTIN</th><th>State</th><th>Purchases</th><th>Actions</th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="table-primary"><span class="avatar-small">${esc(initials(s.name))}</span><strong>${esc(s.name)}</strong></div></td><td>${esc(s.phone||'—')}</td><td>${esc(s.gstin||'Unregistered')}</td><td>${esc(s.state||'—')}</td><td>${db.purchases.filter(p=>p.supplierId===s.id).length}</td><td><div class="table-actions"><button class="tiny-action" title="Edit supplier" data-action="edit-supplier" data-id="${s.id}">${icon('edit')}</button><button class="tiny-action" title="Delete supplier" data-action="delete-supplier" data-id="${s.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No suppliers yet','Add the suppliers you purchase goods from.','<button class="btn btn-primary btn-sm" data-action="new-supplier">Add supplier</button>')}</section>`;}
  function renderExpenses(){const list=db.expenses.filter(e=>[e.description,e.category,e.paymentMethod].join(' ').toLowerCase().includes(pageSearch.toLowerCase()));return `${pageHeader('Expenses','Record operating costs separately from inventory purchases.',`<button class="btn btn-primary" data-action="new-expense">${icon('plus')} Add expense</button>`)}<div class="report-cards"><div class="report-mini"><span>All recorded expenses</span><strong>${money(db.expenses.reduce((s,e)=>s+num(e.amount),0))}</strong></div><div class="report-mini"><span>This month</span><strong>${money(monthExpenses().reduce((s,e)=>s+num(e.amount),0))}</strong></div><div class="report-mini"><span>Expense entries</span><strong>${db.expenses.length}</strong></div></div><div class="toolbar"><div class="toolbar-left"><div class="search-box">${icon('search')}<input id="pageSearch" placeholder="Search expense or category..." value="${esc(pageSearch)}" /></div></div><div class="toolbar-right"><span class="muted">${list.length} entries</span></div></div><section class="content-card table-card">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Payment method</th><th>Amount</th><th>Actions</th></tr></thead><tbody>${list.sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td>${fmtDate(e.date)}</td><td><strong>${esc(e.description)}</strong></td><td>${esc(e.category||'Other')}</td><td>${esc(e.paymentMethod||'—')}</td><td><strong>${money(e.amount)}</strong></td><td><div class="table-actions"><button class="tiny-action" title="Edit expense" data-action="edit-expense" data-id="${e.id}">${icon('edit')}</button><button class="tiny-action" title="Delete expense" data-action="delete-expense" data-id="${e.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No expenses recorded','Add rent, transport, salaries and other operating expenses.','<button class="btn btn-primary btn-sm" data-action="new-expense">Add expense</button>')}</section>`;}
  function renderReports(){const sales=db.invoices.reduce((s,i)=>s+num(i.grandTotal),0),purchase=db.purchases.reduce((s,p)=>s+num(p.total),0),expenses=db.expenses.reduce((s,e)=>s+num(e.amount),0);return `${pageHeader('Reports & exports','Review business activity and download records for your own accounting workflow.',`<button class="btn btn-secondary" data-action="export-csv" data-kind="invoices">${icon('download')} Export invoices CSV</button><button class="btn btn-primary" data-action="export-csv" data-kind="products">${icon('download')} Export stock CSV</button>`)}<div class="note-banner"><strong>Reporting note:</strong> The summaries below use records entered in this browser. They are management reports, not filed GST returns or audited financial statements.</div><div class="report-cards"><div class="report-mini"><span>Sales invoiced</span><strong>${money(sales)}</strong></div><div class="report-mini"><span>Purchases recorded</span><strong>${money(purchase)}</strong></div><div class="report-mini"><span>Operating expenses</span><strong>${money(expenses)}</strong></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">GST summary · sales invoices</div><div class="panel-subtitle">Totals from all invoices recorded so far</div></div></div>${renderGstSummary()}</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Inventory value estimate</div><div class="panel-subtitle">On-hand quantity multiplied by recorded purchase rate</div></div></div><div class="stat-value" style="margin-top:3px">${money(db.products.reduce((s,p)=>s+num(p.stock)*num(p.purchasePrice),0))}</div><div class="stat-foot">Estimated stock cost value · excluding any valuation adjustments</div><div style="margin-top:17px" class="alert-list"><div class="alert-row"><span class="alert-copy"><strong>Total products</strong></span><span class="alert-value">${db.products.length}</span></div><div class="alert-row"><span class="alert-copy"><strong>Low stock items</strong></span><span class="alert-value">${db.products.filter(p=>num(p.stock)<=num(p.lowStock??db.settings.lowStock)).length}</span></div><div class="alert-row"><span class="alert-copy"><strong>Expiry alerts</strong></span><span class="alert-value">${expiryAlerts().length}</span></div></div></section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><div class="panel-title">Customer outstanding</div><div class="panel-subtitle">Unpaid and partially paid invoices by customer</div></div><button class="btn btn-secondary btn-sm" data-action="export-csv" data-kind="outstanding">Export CSV ${icon('download')}</button></div>${outstandingInvoices().length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Invoice</th><th>Date</th><th>Invoice total</th><th>Paid</th><th>Balance due</th></tr></thead><tbody>${outstandingInvoices().map(i=>`<tr><td><strong>${esc(findCustomer(i.customerId)?.name||'—')}</strong></td><td>${esc(i.number)}</td><td>${fmtDate(i.date)}</td><td>${money(i.grandTotal)}</td><td>${money(i.paidAmount)}</td><td><strong>${money(i.grandTotal-i.paidAmount)}</strong></td></tr>`).join('')}</tbody></table></div>`:`<div class="muted" style="font-size:11px;padding:15px 0">There are no outstanding invoices.</div>`}</section>`;}
  function renderGstSummary(){let taxable=0,cgst=0,sgst=0,igst=0;db.invoices.forEach(i=>{taxable+=num(i.taxable);cgst+=num(i.cgst);sgst+=num(i.sgst);igst+=num(i.igst);});return `<div class="alert-list"><div class="alert-row"><span class="alert-copy"><strong>Taxable value</strong></span><span class="alert-value">${money(taxable)}</span></div><div class="alert-row"><span class="alert-copy"><strong>CGST</strong></span><span class="alert-value">${money(cgst)}</span></div><div class="alert-row"><span class="alert-copy"><strong>SGST</strong></span><span class="alert-value">${money(sgst)}</span></div><div class="alert-row"><span class="alert-copy"><strong>IGST</strong></span><span class="alert-value">${money(igst)}</span></div><div class="alert-row"><span class="alert-copy"><strong>Total GST</strong></span><span class="alert-value">${money(cgst+sgst+igst)}</span></div></div>`;}
  function renderSettings(){return `${pageHeader('Settings','Configure your business profile, GST details, document numbering and inventory alerts.','')}
    <div class="settings-layout"><div class="settings-tabs"><button class="settings-tab active" data-settings-tab="business">Business profile</button><button class="settings-tab" data-settings-tab="gst">GST & documents</button><button class="settings-tab" data-settings-tab="inventory">Inventory alerts</button><button class="settings-tab" data-settings-tab="data">Data & backup</button></div>
    <div class="settings-form-card" id="settingsPanel">${settingsPanel('business')}</div></div>`;}
  function settingsPanel(tab){const s=db.settings;if(tab==='business')return `<h3>Business profile</h3><p>These details appear on your quotations and GST invoices.</p><form data-form="settings-business"><div class="form-grid"><div class="field full"><label>Business / trade name <span class="required">*</span></label><input name="businessName" required value="${esc(s.businessName)}" /></div><div class="field"><label>Business phone</label><input name="phone" value="${esc(s.phone)}" placeholder="+91..." /></div><div class="field"><label>Email address</label><input name="email" type="email" value="${esc(s.email)}" /></div><div class="field full"><label>Registered / business address</label><textarea name="address">${esc(s.address)}</textarea></div><div class="field"><label>State</label><input name="state" value="${esc(s.state)}" placeholder="Kerala" /></div><div class="field"><label>GSTIN</label><input name="gstin" value="${esc(s.gstin)}" maxlength="15" placeholder="15-character GSTIN" /></div></div><div class="settings-bottom"><button class="btn btn-primary" type="submit">Save business profile</button></div></form>`;
    if(tab==='gst')return `<h3>GST & document settings</h3><p>Set document numbering and the way product prices are entered.</p><form data-form="settings-gst"><div class="form-grid"><div class="field"><label>Invoice prefix</label><input name="invoicePrefix" value="${esc(s.invoicePrefix)}" /></div><div class="field"><label>Quotation prefix</label><input name="quotePrefix" value="${esc(s.quotePrefix)}" /></div><div class="field"><label>Purchase prefix</label><input name="purchasePrefix" value="${esc(s.purchasePrefix)}" /></div><div class="field"><label>Product price entry</label><select name="pricingMode"><option value="exclusive" ${s.pricingMode==='exclusive'?'selected':''}>Prices exclude GST</option><option value="inclusive" ${s.pricingMode==='inclusive'?'selected':''}>Prices include GST</option></select></div></div><div class="note-banner" style="margin-top:15px"><strong>GST calculation:</strong> Intra-state supplies split tax into CGST and SGST. Inter-state supplies use IGST, based on the business state and customer state entered. Confirm the correct GST classification and rate for each product with your tax adviser.</div><div class="settings-bottom"><button class="btn btn-primary" type="submit">Save GST settings</button></div></form>`;
    if(tab==='inventory')return `<h3>Inventory alert levels</h3><p>Set default thresholds. Individual products can override these values.</p><form data-form="settings-inventory"><div class="form-grid"><div class="field"><label>Default low-stock alert quantity</label><input name="lowStock" type="number" min="0" step="1" value="${num(s.lowStock)}" /></div><div class="field"><label>Default overstock alert quantity</label><input name="overStock" type="number" min="0" step="1" value="${num(s.overStock)}" /></div><div class="field"><label>Expiry warning window (days)</label><input name="expiryDays" type="number" min="1" step="1" value="${num(s.expiryDays)}" /></div></div><div class="note-banner" style="margin-top:15px">Expiry alerts include batches that are already expired and batches expiring within the configured number of days.</div><div class="settings-bottom"><button class="btn btn-primary" type="submit">Save alert settings</button></div></form>`;
    return `<h3>Data & backup</h3><p>Your records are stored in this browser on this device. Export a backup regularly.</p><div class="note-banner"><strong>Important:</strong> This first version does not sync between devices or users. Clearing browser data can remove records unless you have exported a backup.</div><div style="display:flex;gap:9px;flex-wrap:wrap;margin:18px 0"><button class="btn btn-primary" data-action="export-data">${icon('download')} Download full backup (JSON)</button><button class="btn btn-secondary" data-action="import-data">${icon('upload')} Import backup</button></div><div class="modal-section-title">Demo data</div><p style="font-size:10px;color:#98a2b0;margin:0 0 12px">Load a small sample business to explore the screens. This will replace the current workspace data.</p><button class="btn btn-secondary" data-action="load-demo">Load sample data</button><button class="btn btn-danger" style="margin-left:8px" data-action="clear-data">Clear all business data</button>`;}

  function render(){
    $('#crumbTitle').textContent=pageTitle(activePage);$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===activePage));
    const views={dashboard:renderDashboard,customers:renderCustomers,products:renderProducts,quotations:renderQuotations,invoices:renderInvoices,purchases:renderPurchases,suppliers:renderSuppliers,expenses:renderExpenses,reports:renderReports,settings:renderSettings};
    $('#view').innerHTML=(views[activePage]||renderDashboard)();setIcons($('#view'));
    if(activePage==='dashboard')requestAnimationFrame(drawSalesChart);
  }
  function navigate(page){activePage=page;pageSearch='';render();$('#sidebar').classList.remove('open');}
  function modal(title,body,footer='',wide=false){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=body+`<div class="modal-footer">${footer||'<button class="btn btn-secondary" type="button" data-action="close-modal">Close</button>'}</div>`;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');$('.modal-panel').classList.toggle('wide',wide);setIcons($('#modalContent'));$('#modalClose').focus();}
  function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true');$('#modalContent').innerHTML='';}
  const modalButtons=(cancel='Cancel',save='Save')=>`<button class="btn btn-secondary" type="button" data-action="close-modal">${cancel}</button><button class="btn btn-primary" type="submit" form="activeForm">${save}</button>`;
  function openCustomer(id){const c=id?findCustomer(id):{};modal(id?'Edit customer':'Add customer',`<form id="activeForm" data-form="customer" data-id="${id||''}"><div class="form-grid"><div class="field full"><label>Customer / business name <span class="required">*</span></label><input name="name" required value="${esc(c.name||'')}" placeholder="Customer name" /></div><div class="field"><label>Phone number</label><input name="phone" value="${esc(c.phone||'')}" placeholder="+91..." /></div><div class="field"><label>WhatsApp number</label><input name="whatsapp" value="${esc(c.whatsapp||c.phone||'')}" placeholder="Country code + number" /></div><div class="field"><label>Customer type</label><select name="customerType"><option ${c.customerType==='Registered'?'selected':''}>Registered</option><option ${!c.customerType||c.customerType==='Unregistered'?'selected':''}>Unregistered</option></select></div><div class="field"><label>GSTIN (if registered)</label><input name="gstin" maxlength="15" value="${esc(c.gstin||'')}" placeholder="15-character GSTIN" /></div><div class="field"><label>State</label><input name="state" value="${esc(c.state||'')}" placeholder="Kerala" /></div><div class="field"><label>City</label><input name="city" value="${esc(c.city||'')}" /></div><div class="field full"><label>Billing address</label><textarea name="address">${esc(c.address||'')}</textarea></div><div class="field"><label>Credit period (days)</label><input name="creditDays" type="number" min="0" value="${num(c.creditDays)}" /></div><div class="field"><label>WhatsApp communication</label><label class="checkbox-line"><input type="checkbox" name="whatsappConsent" ${c.whatsappConsent?'checked':''}/> Customer has agreed to receive business messages</label></div></div></form><p class="form-note">Use the full WhatsApp number with country code, for example 919876543210. The app opens WhatsApp for you to review and send the message.</p>`,modalButtons(),false);}
  function openSupplier(id){const s=id?findSupplier(id):{};modal(id?'Edit supplier':'Add supplier',`<form id="activeForm" data-form="supplier" data-id="${id||''}"><div class="form-grid"><div class="field full"><label>Supplier / company name <span class="required">*</span></label><input name="name" required value="${esc(s.name||'')}" /></div><div class="field"><label>Contact number</label><input name="phone" value="${esc(s.phone||'')}" /></div><div class="field"><label>GSTIN</label><input name="gstin" maxlength="15" value="${esc(s.gstin||'')}" /></div><div class="field"><label>State</label><input name="state" value="${esc(s.state||'')}" /></div><div class="field"><label>City</label><input name="city" value="${esc(s.city||'')}" /></div><div class="field full"><label>Address</label><textarea name="address">${esc(s.address||'')}</textarea></div></div></form>`,modalButtons());}
  function openProduct(id){const p=id?findProduct(id):{};modal(id?'Edit product':'Add product',`<form id="activeForm" data-form="product" data-id="${id||''}"><div class="form-grid"><div class="field full"><label>Product name <span class="required">*</span></label><input name="name" required value="${esc(p.name||'')}" placeholder="e.g. Basmati Rice" /></div><div class="field"><label>SKU / product code</label><input name="sku" value="${esc(p.sku||'')}" /></div><div class="field"><label>Category</label><input name="category" value="${esc(p.category||'')}" placeholder="Grocery, Household..." /></div><div class="field"><label>HSN code</label><input name="hsn" value="${esc(p.hsn||'')}" /></div><div class="field"><label>Unit</label><select name="unit">${['pcs','packet','box','kg','gram','litre','metre','dozen','bag','set'].map(x=>`<option value="${x}" ${(p.unit||'pcs')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Purchase price (₹)</label><input name="purchasePrice" type="number" min="0" step="0.01" value="${num(p.purchasePrice)}" /></div><div class="field"><label>Selling price (₹) <span class="required">*</span></label><input name="sellingPrice" type="number" min="0" step="0.01" required value="${num(p.sellingPrice)}" /></div><div class="field"><label>GST rate</label><select name="gstRate">${[0,5,12,18,28].map(x=>`<option value="${x}" ${num(p.gstRate)===x?'selected':''}>${x}%</option>`).join('')}</select></div><div class="field"><label>Low-stock alert</label><input name="lowStock" type="number" min="0" value="${p.lowStock??db.settings.lowStock}" /></div><div class="field"><label>Overstock alert</label><input name="overStock" type="number" min="0" value="${p.overStock??db.settings.overStock}" /></div>${!id?`<div class="field"><label>Opening stock</label><input name="openingStock" type="number" min="0" value="0" /></div>`:`<div class="field"><label>Current stock</label><input value="${num(p.stock)} ${esc(p.unit||'pcs')}" disabled /></div>`}<div class="field full"><label class="checkbox-line"><input type="checkbox" name="trackExpiry" ${p.trackExpiry?'checked':''}/> This product has expiry dates / batch tracking</label></div>${!id?`<div class="field"><label>Opening batch number (optional)</label><input name="batchNo" placeholder="Batch number" /></div><div class="field"><label>Opening batch expiry (optional)</label><input name="expiryDate" type="date" min="${today()}" /></div>`:''}</div></form><p class="form-note">GST rate is stored per product. Confirm the correct HSN and tax rate for each item before issuing a tax invoice.</p>`,modalButtons(),false);}
  function openStock(id){const p=id?findProduct(id):null;modal('Adjust stock',`<form id="activeForm" data-form="stock"><div class="form-grid"><div class="field full"><label>Product <span class="required">*</span></label><select name="productId" required><option value="">Select product</option>${db.products.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.name)} · ${num(x.stock)} ${esc(x.unit||'pcs')}</option>`).join('')}</select></div><div class="field"><label>Adjustment type</label><select name="direction"><option value="add">Add stock (+)</option><option value="remove">Remove stock (−)</option></select></div><div class="field"><label>Quantity <span class="required">*</span></label><input name="qty" type="number" min="0.001" step="0.001" required /></div><div class="field"><label>Reason</label><select name="reason"><option>Opening balance</option><option>Physical stock count</option><option>Damaged / expired</option><option>Purchase correction</option><option>Sales return</option><option>Other adjustment</option></select></div><div class="field"><label>Reference / note</label><input name="note" placeholder="Optional reference" /></div><div class="field"><label>Batch number (for additions)</label><input name="batchNo" placeholder="Batch number" /></div><div class="field"><label>Expiry date (optional)</label><input name="expiryDate" type="date" /></div></div></form><p class="form-note">Stock additions and removals are recorded in the movement history. For tracked products, additions can be recorded as a new batch.</p>`,modalButtons());}
  function productOptions(selected=''){return `<option value="">Select product</option>${db.products.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${money(p.sellingPrice)}</option>`).join('')}`;}
  function docLineHtml(item={}){const p=findProduct(item.productId);return `<div class="doc-line"><select class="line-product" required>${productOptions(item.productId||'')}</select><input class="line-qty" type="number" min="0.001" step="0.001" value="${item.qty??1}" aria-label="Quantity"/><input class="line-rate" type="number" min="0" step="0.01" value="${item.rate??p?.sellingPrice??0}" aria-label="Rate"/><input class="line-discount" type="number" min="0" max="100" step="0.01" value="${item.discount??0}" aria-label="Discount percentage"/><button type="button" class="remove-line" title="Remove item">${icon('close')}</button></div>`;}
  function openDocument(type,fromQuote=null){const isQuote=type==='quotation';const q=fromQuote?db.quotations.find(x=>x.id===fromQuote):null;const title=isQuote?'Create quotation':'Create GST tax invoice';const customerId=q?.customerId||'';const defaultDue=(c)=>{const d=new Date(`${today()}T00:00:00`);d.setDate(d.getDate()+num(c?.creditDays||0));return d.toISOString().slice(0,10);};const c=findCustomer(customerId);
    const initialItems=q?.items?.length?q.items:[{}];
    modal(title,`<form id="activeForm" data-form="document" data-type="${type}" data-quote-id="${fromQuote||''}"><div class="form-grid"><div class="field"><label>Customer <span class="required">*</span></label><select name="customerId" required><option value="">Select customer</option>${db.customers.map(x=>`<option value="${x.id}" ${x.id===customerId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>${isQuote?'Quotation date':'Invoice date'}</label><input type="date" name="date" value="${q?.date||today()}" required /></div><div class="field"><label>${isQuote?'Valid until':'Payment due date'}</label><input type="date" name="dueDate" value="${isQuote?(q?.validUntil||today()):defaultDue(c)}" /></div>${!isQuote?`<div class="field"><label>Amount received now (₹)</label><input type="number" name="paidAmount" min="0" step="0.01" value="0" /></div>`:`<div class="field"><label>Reference / subject (optional)</label><input name="reference" value="${esc(q?.reference||'')}" placeholder="Customer enquiry / project" /></div>`}</div><div class="modal-section-title">Items & pricing</div><div class="line-items"><div class="line-item-head"><span>Product</span><span>Qty</span><span>Rate (₹)</span><span>Disc %</span><span></span></div><div id="docLines">${initialItems.map(x=>docLineHtml(x)).join('')}</div></div><div style="margin-top:9px"><button class="btn btn-secondary btn-sm" type="button" data-action="add-doc-line">${icon('plus')} Add another item</button></div><div class="doc-summary"><div class="doc-summary-note">${db.settings.pricingMode==='inclusive'?'Product rates are treated as GST-inclusive.':'Product rates are treated as GST-exclusive.'} Tax is calculated from the product GST rate and the customer state. Please verify place of supply and tax applicability before issuing.</div><div class="totals-box" id="docTotals"></div></div><div class="field full" style="margin-top:13px"><label>Notes / terms</label><textarea name="notes" placeholder="Optional notes for the customer">${esc(q?.notes||'')}</textarea></div></form>`,modalButtons('Cancel',isQuote?'Save quotation':'Create invoice'),true);
    updateDocTotals();
  }
  function readDocItems(){return $$('.doc-line',$('#modalContent')).map(row=>{const productId=$('.line-product',row).value;const p=findProduct(productId);return {productId,qty:num($('.line-qty',row).value),rate:num($('.line-rate',row).value),discount:num($('.line-discount',row).value),gstRate:num(p?.gstRate),name:p?.name,hsn:p?.hsn,unit:p?.unit,sku:p?.sku};}).filter(x=>x.productId&&x.qty>0);}
  function updateDocTotals(){const form=$('#activeForm');if(!form||form.dataset.form!=='document')return;const customer=findCustomer(form.elements.customerId.value);const items=readDocItems();const t=calcTotals(items,customer?.state);const rows=`<div class="total-row"><span>Taxable value</span><strong>${money(t.taxable)}</strong></div>${t.inter?`<div class="total-row"><span>IGST</span><strong>${money(t.igst)}</strong></div>`:`<div class="total-row"><span>CGST</span><strong>${money(t.cgst)}</strong></div><div class="total-row"><span>SGST</span><strong>${money(t.sgst)}</strong></div>`}<div class="total-row"><span>Discount</span><strong>${money(t.discount)}</strong></div><div class="total-row"><span>Round off</span><strong>${money(t.roundOff)}</strong></div><div class="total-row grand"><span>Grand total</span><strong>${money(t.grand)}</strong></div>`;$('#docTotals').innerHTML=rows;}
  function openPurchase(){modal('Record supplier purchase',`<form id="activeForm" data-form="purchase"><div class="form-grid"><div class="field"><label>Supplier <span class="required">*</span></label><select name="supplierId" required><option value="">Select supplier</option>${db.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Purchase date</label><input type="date" name="date" value="${today()}" required /></div></div><div class="modal-section-title">Purchased items</div><div class="line-items"><div class="line-item-head" style="grid-template-columns:2fr .7fr 1fr 1fr 30px"><span>Product</span><span>Qty</span><span>Cost / unit</span><span>Expiry date</span><span></span></div><div id="purchaseLines">${purchaseLineHtml()}</div></div><div style="margin-top:9px"><button class="btn btn-secondary btn-sm" type="button" data-action="add-purchase-line">${icon('plus')} Add item</button></div><div class="doc-summary"><div class="doc-summary-note">On saving, received quantities will be added to stock. For products with expiry tracking, enter batch and expiry details.</div><div class="totals-box" id="purchaseTotals"></div></div><div class="field full" style="margin-top:13px"><label>Reference / notes</label><input name="notes" /></div></form>`,modalButtons('Cancel','Save purchase'),true);updatePurchaseTotals();}
  function purchaseLineHtml(){return `<div class="doc-line purchase-line" style="grid-template-columns:2fr .7fr 1fr 1fr 30px"><select class="purchase-product">${productOptions()}</select><input class="purchase-qty" type="number" min="0.001" step="0.001" value="1"/><input class="purchase-rate" type="number" min="0" step="0.01" value="0"/><input class="purchase-expiry" type="date"/><button type="button" class="remove-line" title="Remove item">${icon('close')}</button></div>`;}
  function updatePurchaseTotals(){const box=$('#purchaseTotals');if(!box)return;const total=$$('.purchase-line',$('#modalContent')).reduce((s,r)=>s+num($('.purchase-qty',r).value)*num($('.purchase-rate',r).value),0);box.innerHTML=`<div class="total-row"><span>Purchase value</span><strong>${money(total)}</strong></div><div class="total-row grand"><span>Total cost</span><strong>${money(total)}</strong></div>`;}
  function openExpense(id){const e=id?db.expenses.find(x=>x.id===id):{};modal(id?'Edit expense':'Record expense',`<form id="activeForm" data-form="expense" data-id="${id||''}"><div class="form-grid"><div class="field full"><label>Description <span class="required">*</span></label><input name="description" required value="${esc(e.description||'')}" placeholder="e.g. Shop rent" /></div><div class="field"><label>Category</label><select name="category">${['Rent','Electricity','Transport','Salary','Packing','Repairs & maintenance','Marketing','Bank charges','Other'].map(x=>`<option ${((e.category||'Other')===x)?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Amount (₹) <span class="required">*</span></label><input name="amount" type="number" min="0.01" step="0.01" required value="${e.amount??''}" /></div><div class="field"><label>Date</label><input type="date" name="date" value="${e.date||today()}" required /></div><div class="field"><label>Payment method</label><select name="paymentMethod">${['Cash','UPI','Bank transfer','Card','Other'].map(x=>`<option ${e.paymentMethod===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(e.notes||'')}</textarea></div></div></form>`,modalButtons());}
  function openPayment(id){const i=db.invoices.find(x=>x.id===id);if(!i)return;const due=Math.max(0,num(i.grandTotal)-num(i.paidAmount));modal('Record customer payment',`<form id="activeForm" data-form="payment" data-id="${id}"><div class="note-banner">Invoice <strong>${esc(i.number)}</strong> · ${esc(findCustomer(i.customerId)?.name||'Customer')}<br/>Total ${money(i.grandTotal)} · Paid ${money(i.paidAmount)} · Balance ${money(due)}</div><div class="form-grid"><div class="field"><label>Amount received (₹) <span class="required">*</span></label><input name="amount" type="number" min="0.01" max="${due.toFixed(2)}" step="0.01" required value="${due.toFixed(2)}" /></div><div class="field"><label>Payment date</label><input name="date" type="date" value="${today()}" /></div><div class="field"><label>Payment method</label><select name="method">${['Cash','UPI','Bank transfer','Card','Cheque','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Reference</label><input name="reference" placeholder="UPI / transaction reference" /></div></div></form>`,modalButtons('Cancel','Save payment'));}

  function generateNumber(prefix,collection){const year=new Date().getFullYear();const count=collection.filter(x=>(x.number||'').includes(String(year))).length+1;return `${prefix||'DOC'}/${year}/${String(count).padStart(4,'0')}`;}
  function recordMovement(productId,delta,reason,note='',batchInfo={}){const p=findProduct(productId);if(!p)return;p.stock=num(p.stock)+delta;p.batches=Array.isArray(p.batches)?p.batches:[];
    if(delta>0 && (p.trackExpiry||batchInfo.expiryDate||batchInfo.batchNo)){const b={id:uid(),batchNo:batchInfo.batchNo||`B-${Date.now().toString().slice(-5)}`,qty:delta,expiryDate:batchInfo.expiryDate||'',purchaseDate:batchInfo.purchaseDate||today()};p.batches.push(b);}
    if(delta<0&&p.batches.length){let remaining=Math.abs(delta);const batches=[...p.batches].filter(b=>num(b.qty)>0).sort((a,b)=>(a.expiryDate||'9999').localeCompare(b.expiryDate||'9999'));for(const b of batches){if(remaining<=0)break;const take=Math.min(num(b.qty),remaining);b.qty=num(b.qty)-take;remaining-=take;}}
    db.stockMovements.unshift({id:uid(),productId,productName:p.name,delta,reason,note,date:today(),at:new Date().toISOString()});
  }
  function submitForm(form){const fd=new FormData(form);const v=Object.fromEntries(fd.entries());const id=form.dataset.id;
    switch(form.dataset.form){
      case 'customer':{const obj={id:id||uid(),name:v.name.trim(),phone:v.phone.trim(),whatsapp:v.whatsapp.trim(),customerType:v.customerType,gstin:v.gstin.trim().toUpperCase(),state:v.state.trim(),city:v.city.trim(),address:v.address.trim(),creditDays:num(v.creditDays),whatsappConsent:fd.has('whatsappConsent')};if(id)db.customers=db.customers.map(x=>x.id===id?obj:x);else db.customers.unshift(obj);saveData();closeModal();render();toast(id?'Customer updated':'Customer added');break;}
      case 'supplier':{const obj={id:id||uid(),name:v.name.trim(),phone:v.phone.trim(),gstin:v.gstin.trim().toUpperCase(),state:v.state.trim(),city:v.city.trim(),address:v.address.trim()};if(id)db.suppliers=db.suppliers.map(x=>x.id===id?obj:x);else db.suppliers.unshift(obj);saveData();closeModal();render();toast(id?'Supplier updated':'Supplier added');break;}
      case 'product':{const existing=id?findProduct(id):null;const p={id:id||uid(),name:v.name.trim(),sku:v.sku.trim(),category:v.category.trim(),hsn:v.hsn.trim(),unit:v.unit,purchasePrice:num(v.purchasePrice),sellingPrice:num(v.sellingPrice),gstRate:num(v.gstRate),lowStock:num(v.lowStock),overStock:num(v.overStock),trackExpiry:fd.has('trackExpiry'),stock:existing?num(existing.stock):0,batches:existing?(existing.batches||[]):[]};if(id)db.products=db.products.map(x=>x.id===id?p:x);else{db.products.unshift(p);const opening=num(v.openingStock);if(opening>0)recordMovement(p.id,opening,'Opening balance','Initial product stock',{batchNo:v.batchNo,expiryDate:v.expiryDate,purchaseDate:today()});}saveData();closeModal();render();toast(id?'Product updated':'Product added');break;}
      case 'stock':{const p=findProduct(v.productId);const qty=num(v.qty);if(!p||qty<=0){toast('Select a product and enter a quantity.','error');return;}const delta=v.direction==='remove'?-qty:qty;if(delta<0&&Math.abs(delta)>num(p.stock)){if(!confirm(`This adjustment will make ${p.name} stock negative. Continue?`))return;}recordMovement(p.id,delta,v.reason,v.note,{batchNo:v.batchNo,expiryDate:v.expiryDate,purchaseDate:today()});saveData();closeModal();render();toast('Stock adjustment saved');break;}
      case 'document':{const type=form.dataset.type;const c=findCustomer(v.customerId);const items=readDocItems();if(!items.length){toast('Add at least one valid product line.','error');return;}const totals=calcTotals(items,c?.state);if(type==='invoice'){const shortages=items.filter(x=>num(findProduct(x.productId)?.stock)<x.qty);if(shortages.length&&!confirm(`Some products have insufficient stock (${shortages.map(x=>x.name).join(', ')}). Continue and allow negative stock?`))return;}
        if(type==='quotation'){const number=generateNumber(db.settings.quotePrefix,db.quotations);const q={id:uid(),number,customerId:c.id,date:v.date,validUntil:v.dueDate,reference:v.reference||'',notes:v.notes||'',items, ...totals,grandTotal:totals.grand,status:'Draft',createdAt:new Date().toISOString()};db.quotations.unshift(q);const from=form.dataset.quoteId;if(from){const old=db.quotations.find(x=>x.id===from);if(old)old.status='Revised';}}
        else{const number=generateNumber(db.settings.invoicePrefix,db.invoices);const paid=Math.min(totals.grand,Math.max(0,num(v.paidAmount)));const invoice={id:uid(),number,customerId:c.id,date:v.date,dueDate:v.dueDate,notes:v.notes||'',items,...totals,grandTotal:totals.grand,paidAmount:paid,payments:paid?[{id:uid(),amount:paid,date:v.date,method:'Initial payment',reference:''}]:[],createdAt:new Date().toISOString()};db.invoices.unshift(invoice);items.forEach(x=>recordMovement(x.productId,-x.qty,`Sale ${number}`,`Invoice ${number}`));}
        saveData();closeModal();render();toast(type==='quotation'?'Quotation created':'Tax invoice created');break;}
      case 'purchase':{const supplier=findSupplier(v.supplierId);const rows=$$('.purchase-line',$('#modalContent')).map(r=>({productId:$('.purchase-product',r).value,qty:num($('.purchase-qty',r).value),rate:num($('.purchase-rate',r).value),expiryDate:$('.purchase-expiry',r).value})).filter(x=>x.productId&&x.qty>0);if(!rows.length){toast('Add at least one product to the purchase.','error');return;}const total=rows.reduce((s,x)=>s+x.qty*x.rate,0);const number=generateNumber(db.settings.purchasePrefix,db.purchases);const pur={id:uid(),number,supplierId:supplier.id,date:v.date,items:rows,total,notes:v.notes||'',createdAt:new Date().toISOString()};db.purchases.unshift(pur);rows.forEach(x=>{const p=findProduct(x.productId);if(p){p.purchasePrice=x.rate;recordMovement(p.id,x.qty,`Purchase ${number}`,`Received from ${supplier.name}`,{batchNo:`${number}-${p.sku||p.id.slice(-4)}`,expiryDate:x.expiryDate,purchaseDate:v.date});}});saveData();closeModal();render();toast('Purchase recorded and stock updated');break;}
      case 'expense':{const obj={id:id||uid(),description:v.description.trim(),category:v.category,amount:num(v.amount),date:v.date,paymentMethod:v.paymentMethod,notes:v.notes};if(id)db.expenses=db.expenses.map(x=>x.id===id?obj:x);else db.expenses.unshift(obj);saveData();closeModal();render();toast(id?'Expense updated':'Expense recorded');break;}
      case 'payment':{const invoice=db.invoices.find(x=>x.id===id);const amount=num(v.amount);const due=Math.max(0,num(invoice.grandTotal)-num(invoice.paidAmount));if(amount<=0||amount>due+.009){toast('Enter a valid payment amount up to the balance due.','error');return;}invoice.paidAmount=num(invoice.paidAmount)+amount;invoice.payments=invoice.payments||[];invoice.payments.push({id:uid(),amount,date:v.date,method:v.method,reference:v.reference});saveData();closeModal();render();toast('Payment recorded');break;}
      case 'settings-business':Object.assign(db.settings,{businessName:v.businessName.trim(),phone:v.phone.trim(),email:v.email.trim(),address:v.address.trim(),state:v.state.trim(),gstin:v.gstin.trim().toUpperCase()});saveData();render();toast('Business profile saved');break;
      case 'settings-gst':Object.assign(db.settings,{invoicePrefix:v.invoicePrefix.trim()||'INV',quotePrefix:v.quotePrefix.trim()||'QT',purchasePrefix:v.purchasePrefix.trim()||'PUR',pricingMode:v.pricingMode});saveData();render();toast('GST and document settings saved');break;
      case 'settings-inventory':Object.assign(db.settings,{lowStock:num(v.lowStock),overStock:num(v.overStock),expiryDays:Math.max(1,num(v.expiryDays))});saveData();render();toast('Inventory alerts saved');break;
    }
  }

  function buildDocumentHtml(doc,type){const isQuote=type==='quotation';const customer=findCustomer(doc.customerId)||{};const s=db.settings;const rows=(doc.items||[]).map((x,i)=>{const gross=num(x.qty)*num(x.rate);const discount=gross*num(x.discount)/100;const net=gross-discount;const gst=num(x.gstRate);const taxable=(s.pricingMode==='inclusive'&&gst>0)?net/(1+gst/100):net;const tax=taxable*gst/100;return `<tr><td>${i+1}</td><td><strong>${esc(x.name)}</strong><br><small>HSN: ${esc(x.hsn||'—')}</small></td><td>${num(x.qty)} ${esc(x.unit||'')}</td><td>${money(x.rate)}</td><td>${num(x.discount)}%</td><td>${money(taxable)}</td><td>${gst}%</td><td>${money(tax)}</td><td>${money(taxable+tax)}</td></tr>`;}).join('');const taxRows=doc.inter?`<tr><td>IGST</td><td>${money(doc.igst)}</td></tr>`:`<tr><td>CGST</td><td>${money(doc.cgst)}</td></tr><tr><td>SGST</td><td>${money(doc.sgst)}</td></tr>`;const status=type==='invoice'?invoiceStatus(doc)[0]:doc.status||'Draft';
    return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(doc.number)}</title><style>*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#1d2738;margin:0;padding:28px}h1{font-size:21px;margin:0 0 5px}h2{font-size:14px;margin:0 0 7px}.muted{color:#687487;font-size:10px;line-height:1.5}.top{display:flex;justify-content:space-between;border-bottom:2px solid #263a60;padding-bottom:17px}.doc-title{text-align:right}.doc-title h1{letter-spacing:1px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:19px 0}.box{border:1px solid #dfe4ec;padding:11px;border-radius:5px}.label{font-size:9px;color:#768297;text-transform:uppercase;letter-spacing:.7px;margin-bottom:6px}.box strong{font-size:12px}table{width:100%;border-collapse:collapse;margin-top:14px}th{background:#f1f4f9;color:#43516a;text-align:left;font-size:9px;text-transform:uppercase;letter-spacing:.4px}td,th{border:1px solid #dfe4ec;padding:8px 6px;font-size:10px;vertical-align:top}td small{color:#7d899a}.summary{margin:15px 0 0 auto;width:280px}.summary td{border:0;border-bottom:1px solid #edf0f4}.summary tr:last-child td{font-weight:bold;font-size:13px;border-top:2px solid #34496e}.notes{margin-top:22px;border-top:1px solid #dfe4ec;padding-top:12px}.foot{display:flex;justify-content:space-between;gap:15px;margin-top:45px}.sign{width:180px;border-top:1px solid #9aa5b4;text-align:center;padding-top:7px;font-size:10px}.print-btn{position:fixed;right:18px;top:16px;padding:10px 15px;background:#315fe0;color:white;border:0;border-radius:6px}@media print{body{padding:0}.print-btn{display:none}}@page{size:A4;margin:14mm}</style></head><body><button class="print-btn" onclick="window.print()">Print / Save PDF</button><div class="top"><div><h2>${esc(s.businessName)}</h2><div class="muted">${esc(s.address).replace(/\n/g,'<br>')}<br>State: ${esc(s.state)}<br>${s.phone?'Phone: '+esc(s.phone)+'<br>':''}${s.email?'Email: '+esc(s.email)+'<br>':''}GSTIN: ${esc(s.gstin||'Not provided')}</div></div><div class="doc-title"><h1>${isQuote?'QUOTATION':'TAX INVOICE'}</h1><div class="muted">${isQuote?'Quotation':'Invoice'} No: <strong>${esc(doc.number)}</strong><br>Date: ${fmtDate(doc.date)}<br>${isQuote?'Valid until: '+fmtDate(doc.validUntil):'Due date: '+fmtDate(doc.dueDate)}<br>Status: ${esc(status)}</div></div></div><div class="meta"><div class="box"><div class="label">Bill to</div><strong>${esc(customer.name||'')}</strong><div class="muted">${esc(customer.address||'')}<br>${esc(customer.city||'')} ${esc(customer.state||'')}<br>${customer.phone?'Phone: '+esc(customer.phone)+'<br>':''}GSTIN: ${esc(customer.gstin||'Unregistered')}</div></div><div class="box"><div class="label">Supply details</div><strong>Place of supply: ${esc(customer.state||s.state||'')}</strong><div class="muted">Supply type: ${doc.inter?'Inter-state (IGST)':'Intra-state (CGST + SGST)'}<br>Currency: INR<br>Price mode: ${s.pricingMode==='inclusive'?'GST inclusive':'GST exclusive'}</div></div></div><table><thead><tr><th>#</th><th>Product / HSN</th><th>Qty</th><th>Rate</th><th>Disc.</th><th>Taxable</th><th>GST</th><th>Tax amt.</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><table class="summary"><tbody><tr><td>Taxable value</td><td style="text-align:right">${money(doc.taxable)}</td></tr>${taxRows}<tr><td>Discount</td><td style="text-align:right">${money(doc.discount)}</td></tr><tr><td>Round off</td><td style="text-align:right">${money(doc.roundOff)}</td></tr><tr><td>Grand total</td><td style="text-align:right">${money(doc.grandTotal??doc.grand)}</td></tr>${!isQuote?`<tr><td>Amount received</td><td style="text-align:right">${money(doc.paidAmount)}</td></tr><tr><td>Balance due</td><td style="text-align:right">${money(Math.max(0,num(doc.grandTotal)-num(doc.paidAmount)))}</td></tr>`:''}</tbody></table><div class="notes"><strong>Notes / terms</strong><div class="muted">${esc(doc.notes||s.terms||'')}</div></div><div class="foot"><div class="muted">This is a computer-generated ${isQuote?'quotation':'document'}.</div><div class="sign">Authorised signatory<br>${esc(s.businessName)}</div></div></body></html>`;
  }
  function previewDocument(id,type){const collection=type==='quotation'?db.quotations:type==='invoice'?db.invoices:db.purchases;const doc=collection.find(x=>x.id===id);if(!doc)return;if(type==='purchase'){const supplier=findSupplier(doc.supplierId)||{};modal(`Purchase ${doc.number}`,`<div class="note-banner">Supplier: <strong>${esc(supplier.name||'—')}</strong> · Date: ${fmtDate(doc.date)} · Total: ${money(doc.total)}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Qty</th><th>Cost</th><th>Expiry</th></tr></thead><tbody>${doc.items.map(x=>`<tr><td>${esc(findProduct(x.productId)?.name||'Deleted product')}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${fmtDate(x.expiryDate)}</td></tr>`).join('')}</tbody></table></div>`, '<button class="btn btn-primary" data-action="close-modal">Close</button>');return;}modal(`${type==='quotation'?'Quotation':'Invoice'} · ${doc.number}`,`<div class="note-banner">${esc(findCustomer(doc.customerId)?.name||'Customer')} · ${fmtDate(doc.date)} · Total <strong>${money(doc.grandTotal??doc.grand)}</strong></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Qty</th><th>Rate</th><th>GST</th><th>Amount</th></tr></thead><tbody>${doc.items.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${x.gstRate}%</td><td>${money(x.qty*x.rate*(1-num(x.discount)/100))}</td></tr>`).join('')}</tbody></table></div><div class="totals-box" style="margin-top:15px"><div class="total-row"><span>Taxable value</span><strong>${money(doc.taxable)}</strong></div><div class="total-row"><span>${doc.inter?'IGST':'CGST + SGST'}</span><strong>${money(doc.inter?doc.igst:doc.cgst+doc.sgst)}</strong></div><div class="total-row grand"><span>Grand total</span><strong>${money(doc.grandTotal??doc.grand)}</strong></div></div>`, `<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-secondary" data-action="print-document" data-id="${id}" data-kind="${type}">${icon('print')} Print / PDF</button><button class="btn btn-success" data-action="whatsapp-${type}" data-id="${id}">${icon('message')} WhatsApp</button>`,true);}
  function printDocument(id,type){const collection=type==='quotation'?db.quotations:db.invoices;const doc=collection.find(x=>x.id===id);if(!doc)return;const win=window.open('','_blank');if(!win){toast('Allow pop-ups to print or save the document as PDF.','error');return;}win.document.open();win.document.write(buildDocumentHtml(doc,type));win.document.close();win.focus();}
  function shareWhatsApp(id,type){const collection=type==='quotation'?db.quotations:db.invoices;const doc=collection.find(x=>x.id===id);if(!doc)return;const c=findCustomer(doc.customerId);const phone=(c?.whatsapp||c?.phone||'').replace(/\D/g,'');if(!phone){toast('Add a WhatsApp number to this customer first.','error');return;}const total=money(doc.grandTotal??doc.grand);const kind=type==='quotation'?'quotation':'tax invoice';const msg=`Hello ${c.name},\n\nPlease find the ${kind} details below.\nReference: ${doc.number}\nDate: ${fmtDate(doc.date)}\nAmount: ${total}\n\n${db.settings.businessName}\n\nThe document PDF can be attached to this chat after it opens.`;if(type==='quotation'&&doc.status==='Draft'){doc.status='Sent';saveData();}window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener');toast('WhatsApp opened with a prepared message. Attach the PDF manually if required.');}
  function convertQuote(id){const q=db.quotations.find(x=>x.id===id);if(!q||q.status==='Converted'){toast('This quotation has already been converted.','error');return;}if(!confirm(`Convert ${q.number} into a tax invoice? This will reduce stock for the listed items.`))return;const shortages=q.items.filter(x=>num(findProduct(x.productId)?.stock)<x.qty);if(shortages.length&&!confirm(`Some products have insufficient stock (${shortages.map(x=>x.name).join(', ')}). Continue?`))return;const number=generateNumber(db.settings.invoicePrefix,db.invoices);const inv={...structuredClone(q),id:uid(),number,date:today(),dueDate:today(),paidAmount:0,payments:[],createdAt:new Date().toISOString(),sourceQuotation:q.number};delete inv.status;delete inv.validUntil;inv.grandTotal=num(q.grandTotal??q.grand);db.invoices.unshift(inv);q.status='Converted';q.invoiceId=inv.id;q.convertedAt=new Date().toISOString();q.grandTotal=q.grandTotal??q.grand;q.items.forEach(x=>recordMovement(x.productId,-num(x.qty),`Sale ${number}`,`Converted from ${q.number}`));saveData();render();toast(`Quotation converted to ${number}`);}
  function removeRecord(kind,id){const map={customer:'customers',supplier:'suppliers',product:'products',quote:'quotations',expense:'expenses'};const key=map[kind];if(!key)return;const item=db[key].find(x=>x.id===id);if(!item)return;if(kind==='customer'&&(db.invoices.some(x=>x.customerId===id)||db.quotations.some(x=>x.customerId===id))){toast('This customer has invoices or quotations and cannot be deleted.','error');return;}if(kind==='product'&&(db.invoices.some(i=>i.items.some(x=>x.productId===id))||db.purchases.some(p=>p.items.some(x=>x.productId===id)))){toast('This product has transaction history and cannot be deleted.','error');return;}if(!confirm(`Delete ${item.name||item.number||item.description||'this record'}?`))return;db[key]=db[key].filter(x=>x.id!==id);saveData();render();toast('Record deleted');}

  function downloadBlob(content,name,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportData(){downloadBlob(JSON.stringify(db,null,2),`wholesalepro-backup-${today()}.json`,'application/json');toast('Backup downloaded');}
  function exportCSV(kind){let rows=[],filename=`${kind}-${today()}.csv`;const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;
    if(kind==='products'){rows=[['Product','SKU','Category','HSN','Unit','Stock','Purchase price','Selling price','GST %','Stock status'],...db.products.map(p=>[p.name,p.sku,p.category,p.hsn,p.unit,p.stock,p.purchasePrice,p.sellingPrice,p.gstRate,stockStatus(p)[0]])];}
    else if(kind==='outstanding'){rows=[['Customer','Invoice','Date','Invoice total','Paid','Balance due'],...outstandingInvoices().map(i=>[findCustomer(i.customerId)?.name,i.number,i.date,i.grandTotal,i.paidAmount,i.grandTotal-i.paidAmount])];}
    else{rows=[['Invoice','Customer','Date','Due date','Taxable','CGST','SGST','IGST','Grand total','Paid','Balance'],...db.invoices.map(i=>[i.number,findCustomer(i.customerId)?.name,i.date,i.dueDate,i.taxable,i.cgst,i.sgst,i.igst,i.grandTotal,i.paidAmount,i.grandTotal-i.paidAmount])];}
    downloadBlob(rows.map(r=>r.map(q).join(',')).join('\r\n'),filename,'text/csv;charset=utf-8');toast('CSV exported');}
  function importData(){ $('#importFile').click(); }
  function loadDemo(){if(!confirm('Load sample data? This replaces the current workspace records. Export a backup first if you need them.'))return;const s=db.settings;const sample=structuredClone(DEFAULTS);sample.settings={...s,businessName:'Northstar Wholesale Traders',gstin:'32ABCDE1234F1Z5',state:'Kerala',address:'Market Road, Kochi, Kerala'};const c1={id:uid(),name:'ABC Retail Stores',phone:'9876543210',whatsapp:'919876543210',customerType:'Registered',gstin:'32AAACA1111A1Z1',state:'Kerala',city:'Kochi',address:'MG Road, Kochi',creditDays:15,whatsappConsent:true};const c2={id:uid(),name:'Green Basket Mart',phone:'9847012345',whatsapp:'919847012345',customerType:'Unregistered',gstin:'',state:'Tamil Nadu',city:'Coimbatore',address:'RS Puram, Coimbatore',creditDays:7};sample.customers=[c1,c2];const su={id:uid(),name:'Prime Distributors',phone:'9895001122',gstin:'32AACCP1234A1Z9',state:'Kerala',city:'Kochi',address:'Ernakulam'};sample.suppliers=[su];const p1={id:uid(),name:'Basmati Rice 5kg',sku:'RICE005',category:'Grocery',hsn:'100630',unit:'bag',purchasePrice:420,sellingPrice:495,gstRate:5,lowStock:15,overStock:100,trackExpiry:true,stock:75,batches:[{id:uid(),batchNo:'BR-241',qty:45,expiryDate:new Date(Date.now()+20*86400000).toISOString().slice(0,10),purchaseDate:today()},{id:uid(),batchNo:'BR-242',qty:30,expiryDate:new Date(Date.now()+95*86400000).toISOString().slice(0,10),purchaseDate:today()}]};const p2={id:uid(),name:'Sunflower Oil 1L',sku:'OIL001',category:'Grocery',hsn:'151219',unit:'bottle',purchasePrice:105,sellingPrice:125,gstRate:5,lowStock:15,overStock:100,trackExpiry:true,stock:8,batches:[{id:uid(),batchNo:'OIL-08',qty:8,expiryDate:new Date(Date.now()+12*86400000).toISOString().slice(0,10),purchaseDate:today()}]};const p3={id:uid(),name:'Dishwash Liquid 500ml',sku:'HOME011',category:'Household',hsn:'340250',unit:'bottle',purchasePrice:52,sellingPrice:75,gstRate:18,lowStock:15,overStock:100,trackExpiry:false,stock:138,batches:[]};sample.products=[p1,p2,p3];const mkInv=(number,c,p,date,qty,rate,paid)=>{const it=[{productId:p.id,name:p.name,sku:p.sku,hsn:p.hsn,unit:p.unit,qty,rate,discount:0,gstRate:p.gstRate}];const t=calcTotals(it,c.state);return {id:uid(),number,customerId:c.id,date,dueDate:date,items:it,...t,grandTotal:t.grand,paidAmount:paid,payments:[],createdAt:`${date}T10:00:00`};};const d=new Date();const d1=new Date(d.getFullYear(),d.getMonth(),Math.max(1,d.getDate()-2)).toISOString().slice(0,10);sample.invoices=[mkInv('INV/2026/0001',c1,p1,d1,10,495,2000),mkInv('INV/2026/0002',c2,p3,today(),12,75,0)];sample.expenses=[{id:uid(),description:'Warehouse rent',category:'Rent',amount:18000,date:today(),paymentMethod:'Bank transfer',notes:''},{id:uid(),description:'Local delivery',category:'Transport',amount:2500,date:today(),paymentMethod:'UPI',notes:''}];sample.stockMovements=[{id:uid(),productId:p1.id,productName:p1.name,delta:75,reason:'Opening balance',note:'Demo data',date:today()},{id:uid(),productId:p2.id,productName:p2.name,delta:8,reason:'Opening balance',note:'Demo data',date:today()},{id:uid(),productId:p3.id,productName:p3.name,delta:138,reason:'Opening balance',note:'Demo data',date:today()}];db=sample;saveData();navigate('dashboard');toast('Sample data loaded');}
  function clearData(){if(!confirm('Permanently clear all records in this browser? Export a backup first if needed.'))return;db=structuredClone(DEFAULTS);saveData();navigate('dashboard');toast('Workspace cleared');}

  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return;}
    const actionEl=e.target.closest('[data-action]');if(!actionEl)return;const a=actionEl.dataset.action,id=actionEl.dataset.id;
    switch(a){
      case 'close-modal':closeModal();break;
      case 'new-customer':openCustomer();break;case 'edit-customer':openCustomer(id);break;case 'delete-customer':removeRecord('customer',id);break;
      case 'new-supplier':openSupplier();break;case 'edit-supplier':openSupplier(id);break;case 'delete-supplier':removeRecord('supplier',id);break;
      case 'new-product':openProduct();break;case 'edit-product':openProduct(id);break;case 'delete-product':removeRecord('product',id);break;
      case 'stock-adjust':openStock();break;case 'adjust-product':openStock(id);break;
      case 'new-quotation':if(!db.customers.length||!db.products.length){toast('Add at least one customer and one product first.','error');return;}openDocument('quotation');break;
      case 'customer-quote':if(!db.products.length){toast('Add a product before creating a quotation.','error');return;}openDocument('quotation');setTimeout(()=>{const f=$('#activeForm');if(f)f.elements.customerId.value=id;updateDocTotals();},0);break;
      case 'new-invoice':if(!db.customers.length||!db.products.length){toast('Add at least one customer and one product first.','error');return;}openDocument('invoice');break;
      case 'new-purchase':if(!db.suppliers.length||!db.products.length){toast('Add at least one supplier and one product first.','error');return;}openPurchase();break;
      case 'new-expense':openExpense();break;case 'edit-expense':openExpense(id);break;case 'delete-expense':removeRecord('expense',id);break;
      case 'view-quote':previewDocument(id,'quotation');break;case 'view-invoice':previewDocument(id,'invoice');break;case 'view-purchase':previewDocument(id,'purchase');break;
      case 'whatsapp-quote':shareWhatsApp(id,'quotation');break;case 'whatsapp-invoice':shareWhatsApp(id,'invoice');break;
      case 'convert-quote':convertQuote(id);break;case 'accept-quote':{const q=db.quotations.find(x=>x.id===id);if(q&&q.status!=='Converted'){q.status='Accepted';saveData();render();toast('Quotation marked as accepted');}break;}case 'delete-quote':removeRecord('quote',id);break;
      case 'add-payment':openPayment(id);break;
      case 'print-document':printDocument(id,actionEl.dataset.kind);break;
      case 'add-doc-line':$('#docLines').insertAdjacentHTML('beforeend',docLineHtml());updateDocTotals();break;
      case 'add-purchase-line':$('#purchaseLines').insertAdjacentHTML('beforeend',purchaseLineHtml());updatePurchaseTotals();break;
      case 'export-data':exportData();break;case 'import-data':importData();break;case 'export-csv':exportCSV(actionEl.dataset.kind);break;
      case 'load-demo':loadDemo();break;case 'clear-data':clearData();break;
      case 'settings-tab':break;
    }
  });
  document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();submitForm(form);});
  document.addEventListener('input',e=>{if(e.target.id==='pageSearch'){pageSearch=e.target.value;const pos=e.target.selectionStart;render();const inp=$('#pageSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}return;}if(e.target.closest('#docLines')&&e.target.classList.contains('line-rate'))updateDocTotals();if(e.target.closest('#docLines')&&e.target.classList.contains('line-qty'))updateDocTotals();if(e.target.closest('#docLines')&&e.target.classList.contains('line-discount'))updateDocTotals();if(e.target.closest('#purchaseLines'))updatePurchaseTotals();});
  document.addEventListener('change',e=>{if(e.target.id==='chartRange'){chartRange=e.target.value;drawSalesChart();}if(e.target.closest('#docLines')&&e.target.classList.contains('line-product')){const p=findProduct(e.target.value);const row=e.target.closest('.doc-line');if(p){$('.line-rate',row).value=p.sellingPrice;updateDocTotals();}}if(e.target.name==='customerId'&&e.target.closest('[data-form="document"]')){const c=findCustomer(e.target.value);const due=e.target.form.elements.dueDate;if(due&&!e.target.form.elements.reference){const d=new Date(`${today()}T00:00:00`);d.setDate(d.getDate()+num(c?.creditDays));due.value=d.toISOString().slice(0,10);}updateDocTotals();}if(e.target.closest('#purchaseLines')&&e.target.classList.contains('purchase-product')){const p=findProduct(e.target.value);if(p) $('.purchase-rate',e.target.closest('.purchase-line')).value=p.purchasePrice;updatePurchaseTotals();}});
  document.addEventListener('click',e=>{const rem=e.target.closest('.remove-line');if(rem){rem.closest('.doc-line').remove();updateDocTotals();updatePurchaseTotals();}const tab=e.target.closest('[data-settings-tab]');if(tab){$$('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===tab));$('#settingsPanel').innerHTML=settingsPanel(tab.dataset.settingsTab);setIcons($('#settingsPanel'));}});
  $('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  $('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#profileButton').addEventListener('click',()=>navigate('settings'));
  $('#importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());const keys=['customers','suppliers','products','quotations','invoices','purchases','expenses','stockMovements'];if(!parsed||typeof parsed!=='object'||!keys.every(k=>Array.isArray(parsed[k]))||!parsed.settings)throw new Error('This file does not look like a WholesalePro backup.');if(!confirm('Import this backup and replace the current browser workspace?'))return;db={...structuredClone(DEFAULTS),...parsed,settings:{...DEFAULTS.settings,...parsed.settings}};saveData();navigate('dashboard');toast('Backup imported successfully');}catch(err){toast(err.message||'Could not import this file.','error');}finally{e.target.value='';}});
  $('#todayLabel').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});updateProfileInitial();render();
})();
